export function eraseFoliage(d,position,radius){if(!validWorldAsset('foliage',d)||!vec(position,2)||!finite(radius,0))throw Error('폴리지 소거 범위를 확인하세요.');const result={...d,instances:d.instances.filter(i=>Math.hypot(i.position[0]-position[0],i.position[2]-position[1])>radius)};if(isWorldDraft(d)){d.instances=result.instances;return d;}return structuredClone(result);}
